CREATE DATABASE IF NOT EXISTS shorum_mobil CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE shorum_mobil;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(25) NOT NULL,created_at DATETIME NOT NULL,INDEX idx_users_email(email)) ENGINE=InnoDB;
CREATE TABLE cars (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,brand VARCHAR(80) NOT NULL,model VARCHAR(80) NOT NULL,year SMALLINT UNSIGNED NOT NULL,price BIGINT UNSIGNED NOT NULL,mileage INT UNSIGNED NOT NULL DEFAULT 0,transmission ENUM('Manual','Otomatis') NOT NULL,fuel ENUM('Bensin','Diesel','Hybrid','Listrik') NOT NULL,color VARCHAR(50) NOT NULL,city VARCHAR(100) NOT NULL,description TEXT NOT NULL,status ENUM('active','sold') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_cars_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_cars_search(status,brand,price,year),INDEX idx_cars_user(user_id)) ENGINE=InnoDB;
CREATE TABLE car_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,car_id BIGINT UNSIGNED NOT NULL,path VARCHAR(255) NOT NULL,is_primary BOOLEAN NOT NULL DEFAULT FALSE,CONSTRAINT fk_images_car FOREIGN KEY(car_id) REFERENCES cars(id) ON DELETE CASCADE,INDEX idx_images_car(car_id,is_primary)) ENGINE=InnoDB;
CREATE TABLE favorites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,car_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_favorite(user_id,car_id),CONSTRAINT fk_fav_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_fav_car FOREIGN KEY(car_id) REFERENCES cars(id) ON DELETE CASCADE) ENGINE=InnoDB;
